// 功能函数：返回 b 的最长前缀也是 a 的后缀的长度
int overlap(const string& a, const string& b) {
    string s = b + "#" + a; // b 为模式串，a 为文本串
    int n = (int)s.size();
    vector<int> pi(n, 0);
    // 计算 KMP 前缀函数
    for (int i = 1; i < n; ++i) {
        int j = pi[i - 1];
        while (j > 0 && s[i] != s[j]) j = pi[j - 1];
        if (s[i] == s[j]) ++j;
        pi[i] = j;
    }
    return pi.back();
}

